using Ginecologia.Modules.Inventario.Application;
using Ginecologia.Modules.Autorizacion.Api;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
namespace Ginecologia.Modules.Inventario.Api;
public sealed record InventoryItemRequest(string Nombre, string Categoria, string UnidadMedida, int StockActual, int StockMinimo, decimal? PrecioUnitario);
public sealed record UpdateInventoryItemRequest(string Nombre, string Categoria, string UnidadMedida, int StockMinimo, decimal? PrecioUnitario);
public sealed record AdjustStockRequest(int Delta, string Motivo);
public static class InventoryEndpoints
{
 public static IEndpointRouteBuilder MapInventoryEndpoints(this IEndpointRouteBuilder endpoints) { var group = endpoints.MapGroup("/api/inventario").RequireAuthorization(); group.MapGet("/", ListAsync); group.MapGet("/{id:guid}", GetAsync); group.MapGet("/{id:guid}/movimientos", MovementsAsync); group.MapPost("/", CreateAsync).RequireAuthorization(policy => policy.AddRequirements(new PermissionRequirement("inventario.gestionar"))); group.MapPut("/{id:guid}", UpdateAsync).RequireAuthorization(policy => policy.AddRequirements(new PermissionRequirement("inventario.gestionar"))); group.MapPost("/{id:guid}/ajustar-stock", AdjustAsync).RequireAuthorization(policy => policy.AddRequirements(new PermissionRequirement("inventario.gestionar"))); group.MapPost("/{id:guid}/desactivar", DeactivateAsync).RequireAuthorization(policy => policy.AddRequirements(new PermissionRequirement("inventario.gestionar"))); group.MapPost("/{id:guid}/reactivar", ReactivateAsync).RequireAuthorization(policy => policy.AddRequirements(new PermissionRequirement("inventario.gestionar"))); return endpoints; }
 private static async Task<IResult> ListAsync(string? search, string? categoria, int page, int pageSize, ListInventoryItemsUseCase uc, CancellationToken ct, bool soloBajoStock = false) { try { return Results.Ok(await uc.ExecuteAsync(search, categoria, soloBajoStock, page == 0 ? 1 : page, pageSize == 0 ? 20 : pageSize, ct)); } catch (ArgumentException ex) { return Results.BadRequest(new { message = ex.Message }); } }
 private static async Task<IResult> GetAsync(Guid id, GetInventoryItemUseCase uc, CancellationToken ct) { var item = await uc.ExecuteAsync(id, ct); return item is null ? Results.NotFound() : Results.Ok(item); }
 private static async Task<IResult> MovementsAsync(Guid id, int page, int pageSize, ListStockMovementsUseCase uc, CancellationToken ct) { try { return Results.Ok(await uc.ExecuteAsync(id, page == 0 ? 1 : page, pageSize == 0 ? 20 : pageSize, ct)); } catch (ArgumentException ex) { return Results.BadRequest(new { message = ex.Message }); } }
 private static async Task<IResult> CreateAsync(InventoryItemRequest request, CreateInventoryItemUseCase uc, CancellationToken ct) { try { var item = await uc.ExecuteAsync(request.Nombre, request.Categoria, request.UnidadMedida, request.StockActual, request.StockMinimo, request.PrecioUnitario, ct); return Results.Created($"/api/inventario/{item.Id}", item); } catch (ArgumentException ex) { return Results.BadRequest(new { message = ex.Message }); } }
 private static async Task<IResult> UpdateAsync(Guid id, UpdateInventoryItemRequest request, UpdateInventoryItemUseCase uc, CancellationToken ct) => await Run(() => uc.ExecuteAsync(id, request.Nombre, request.Categoria, request.UnidadMedida, request.StockMinimo, request.PrecioUnitario, ct));
 private static async Task<IResult> AdjustAsync(Guid id, AdjustStockRequest request, HttpContext context, AdjustStockUseCase uc, CancellationToken ct) { if (request.Delta == 0) return Results.BadRequest(new { message = "El ajuste debe ser distinto de cero." }); if (!Guid.TryParse(context.User.FindFirst("sub")?.Value, out var userId)) return Results.Unauthorized(); return await Run(() => uc.ExecuteAsync(id, request.Delta, request.Motivo, userId, ct)); }
 private static async Task<IResult> DeactivateAsync(Guid id, DeactivateInventoryItemUseCase uc, CancellationToken ct) => await Run(() => uc.ExecuteAsync(id, ct)); private static async Task<IResult> ReactivateAsync(Guid id, ReactivateInventoryItemUseCase uc, CancellationToken ct) => await Run(() => uc.ExecuteAsync(id, ct));
 private static async Task<IResult> Run(Func<Task<InventoryItemDto>> action) { try { return Results.Ok(await action()); } catch (InventoryItemNotFoundException) { return Results.NotFound(); } catch (ArgumentException ex) { return Results.BadRequest(new { message = ex.Message }); } catch (InvalidOperationException ex) { return Results.BadRequest(new { message = ex.Message }); } }
}
